-- Nhóm món để lọc ở Khám phá; xếp theo chữ đầu tên món vì nhóm của Viện lẫn lộn (có cả "Cơm, cháo, xôi" và "Bún, cơm, xôi, cháo")
-- Xét lần lượt các nhóm dưới đây, không khớp nhóm nào thì là món khác (99 món)
ALTER TABLE mon_tra_cuu ADD COLUMN nhom_mon TEXT NOT NULL DEFAULT 'mon_khac'
  CHECK (nhom_mon IN ('bun_pho', 'com_chao_xoi', 'che_do_uong', 'banh', 'mon_khac'));

